  function iconFor(category){return ({text:'≡',zip:'▤',tar:'▤',gzip:'▤',blend:'◈',model:'⬡',image:'▧',audio:'♫',video:'▣',pdf:'▣',sqlite:'▦',ole:'▤',font:'Aa',binary:'◇'})[category]||'◇'}
  function orderedFiles(){const rows=[...state.files];const sort=state.sort;if(sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'})||a.id-b.id);else if(sort==='size')rows.sort((a,b)=>b.file.size-a.file.size||a.id-b.id);else if(sort==='modified')rows.sort((a,b)=>b.file.lastModified-a.file.lastModified||a.id-b.id);return rows}
  function updateHeaderControls(){const enabled=state.active!==null&&state.files.some(x=>x.id===state.active);refs.download.disabled=!enabled;refs.report.disabled=!enabled;refs.remove.disabled=!enabled;const ids=orderedFiles().map(x=>x.id),index=ids.indexOf(state.active);refs.previous.disabled=index<=0;refs.next.disabled=index<0||index>=ids.length-1}
  function adjacentFile(direction){const ids=orderedFiles().map(x=>x.id),at=ids.indexOf(state.active),next=at+direction;if(at>=0&&next>=0&&next<ids.length)selectFile(ids[next])}
  async function addFiles(inputFiles){let newOnes=[];for(const file of inputFiles){if(!(file instanceof Blob)||!file.name)continue;if(state.files.length>=500){toast('Session limit: 500 files');break}const rec={id:++state.sequence,file,name:file._readerPath||file.webkitRelativePath||file.name,detected:null,hash:null};state.files.push(rec);newOnes.push(rec)}renderFileList();updateHeaderControls();if(newOnes.length)await selectFile(newOnes[0].id)}
  function renderFileList(){refs.count.textContent=String(state.files.length);refs.list.replaceChildren();const query=refs.search.value.toLowerCase().trim();const visible=orderedFiles().filter(r=>r.name.toLowerCase().includes(query));if(!visible.length){refs.list.append(newEl('p','empty-list',query?'No matches':'No files opened'));return}for(const r of visible){const row=newEl('button','file-item'+(r.id===state.active?' selected':''));row.type='button';row.title=r.name;row.dataset.fileId=String(r.id);row.setAttribute('aria-current',r.id===state.active?'true':'false');const glyph=newEl('span','file-glyph',iconFor(r.detected?.category||'binary'));const words=newEl('span','file-item-words');words.append(newEl('div','file-item-name',r.name.split('/').pop()),newEl('div','file-item-meta',fmtSize(r.file.size)));row.append(glyph,words);row.addEventListener('click',()=>selectFile(r.id));refs.list.append(row)}}
  function clearSession(){state.files=[];state.active=null;state.generation++;releaseUrls();refs.welcome.hidden=false;refs.content.hidden=true;refs.name.textContent='Universal file viewer';refs.subtitle.textContent='Open any file to inspect its contents';refs.icon.textContent='◇';refs.inspector.replaceChildren(newEl('p','muted','Select a file to view its properties and detected format.'));setStatus('Ready');refs.search.value='';renderFileList();updateHeaderControls()}
  function removeSelected(){const at=state.files.findIndex(x=>x.id===state.active);if(at<0)return;state.files.splice(at,1);state.generation++;releaseUrls();if(!state.files.length){clearSession();return}const near=state.files[Math.min(at,state.files.length-1)];selectFile(near.id);toast('Removed from this session')}
  async function selectFile(id){const r=state.files.find(x=>x.id===id);if(!r)return;state.active=id;state.tab='preview';state.generation++;releaseUrls();updateHeaderControls();const myGen=state.generation;refs.name.textContent=r.name.split('/').pop();refs.subtitle.textContent=`${fmtSize(r.file.size)}  ·  Inspecting format...`;refs.icon.textContent='◇';refs.welcome.hidden=true;refs.content.hidden=false;refs.content.replaceChildren(newEl('div','loading','Inspecting file...'));refs.inspector.replaceChildren(newEl('p','muted','Inspecting properties...'));renderFileList();setActiveTab();try{r.detected=detectType(r.file,await readHead(r.file));if(!isCurrent(myGen))return;refs.icon.textContent=iconFor(r.detected.category);refs.subtitle.textContent=`${r.detected.signature}  ·  ${fmtSize(r.file.size)}`;renderInspector(r);renderFileList();updateHeaderControls();await renderCurrent()}catch(e){if(isCurrent(myGen))errorPanel(e)}}
  function inspectorPair(label,value,mono=false){const wrap=newEl('div','property');wrap.append(newEl('div','property-label',label),newEl('div','property-value'+(mono?' mono':''),value));return wrap}
  function renderInspector(r){const d=r.detected;refs.inspector.replaceChildren();const pill=newEl('span','type-pill',d.category.toUpperCase());refs.inspector.append(inspectorPair('Detected type',d.signature),pill,newEl('div','property',''));refs.inspector.append(inspectorPair('Name',r.name),inspectorPair('Size',`${fmtSize(r.file.size)} (${r.file.size.toLocaleString('en-US')} bytes)`),inspectorPair('Extension',d.extension),inspectorPair('Detection method',d.confidence),inspectorPair('MIME reported',d.mime),inspectorPair('First bytes',d.magic||'Empty file',true));if(r.file.lastModified)refs.inspector.append(inspectorPair('Last modified',new Date(r.file.lastModified).toLocaleString()));
    const hashBox=newEl('div','property');hashBox.append(newEl('div','property-label','SHA-256 fingerprint'));const result=newEl('div','checksum-value',r.hash||'Not calculated');hashBox.append(result);const compute=button(r.hash?'Copy SHA-256':'Calculate SHA-256',async()=>{if(r.hash){await copyToClipboard(r.hash);return}if(r.file.size>256*1024*1024){toast('SHA-256 is limited to 256 MB to protect browser memory');return}if(!globalThis.crypto?.subtle){toast('This browser does not expose the Web Crypto API in this context');return}compute.disabled=true;compute.textContent='Calculating...';try{const digest=await crypto.subtle.digest('SHA-256',await r.file.arrayBuffer());r.hash=hex(new Uint8Array(digest));if(state.active===r.id){result.textContent=r.hash;compute.textContent='Copy SHA-256';compute.disabled=false}}catch(e){if(state.active===r.id){result.textContent='Hash calculation unavailable';compute.disabled=false;compute.textContent='Retry SHA-256'}}});compute.classList.add('checksum-control');hashBox.append(compute);refs.inspector.append(hashBox,inspectorPair('Privacy','Processed locally in this tab; no file upload.'))}
  async function copyToClipboard(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard')}catch(e){const field=newEl('textarea');field.value=text;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();toast(ok?'Copied to clipboard':'Clipboard permission unavailable')}}
  function exportReport(){const r=state.files.find(x=>x.id===state.active);if(!r?.detected)return;const d=r.detected,report={application:'kayralrics.com - file reader',version:'2.0',generatedAt:new Date().toISOString(),name:r.name,sizeBytes:r.file.size,lastModified:r.file.lastModified?new Date(r.file.lastModified).toISOString():null,format:{category:d.category,signature:d.signature,extension:d.extension,detectionMethod:d.confidence,reportedMime:d.mime,magicBytes:d.magic},sha256:r.hash||null,notes:'The SHA-256 is null until calculated. Unsupported formats are inspectable as raw bytes; semantic decoding is not guaranteed.'};downloadFile(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),safeName(r.name.split('/').pop())+'.report.json');toast('Local report exported')}
  function setActiveTab(){for(const btn of refs.tabBar.querySelectorAll('[data-tab]')){const yes=btn.dataset.tab===state.tab;btn.classList.toggle('active',yes);btn.setAttribute('aria-selected',yes?'true':'false')}}
  async function renderCurrent(){const r=state.files.find(x=>x.id===state.active);if(!r||!r.detected)return;const gen=++state.generation;releaseUrls();refs.content.replaceChildren(newEl('div','loading','Opening view...'));setStatus('Working locally...');try{let output;if(state.tab==='preview')output=await preview(r);else if(state.tab==='structure')output=await structure(r);else if(state.tab==='text')output=await textView(r);else if(state.tab==='hex')output=await hexView(r,0);else output=await detailsView(r);if(!isCurrent(gen))return;refs.content.replaceChildren(output);refs.scroll.scrollTop=0;setStatus(`${r.detected.signature} · ${fmtSize(r.file.size)} · Local`)}catch(e){if(isCurrent(gen))errorPanel(e)}}
