  function notice(msg,tone='neutral'){return newEl('div','notice'+(tone==='neutral'?' neutral':''),msg)}
  function fallbackNote(msg){const box=newEl('div','panel');box.append(newEl('h3','panel-heading','Universal fallback'),newEl('p','muted',msg||'Full interpretation is not supported for this format. The Hex and Text tabs provide raw access to its contents.'));return box}
  function panel(title,...children){const p=newEl('section','panel');p.append(newEl('h3','panel-heading',title));for(const c of children){if(c!==null&&c!==undefined)p.append(c instanceof Node?c:newEl('p','muted',String(c)))}return p}
  function metrics(items){const e=newEl('div','summary-grid');for(const [label,value]of items){const m=newEl('div','metric');m.append(newEl('div','metric-value',value),newEl('div','metric-label',label));e.append(m)}return e}
  function kv(data){const e=newEl('div','kv-table');for(const [key,val]of data){e.append(newEl('div','',key),newEl('div','',Array.isArray(val)?val.join(', '):String(val??'—')))}return e}
  function table(headers,rows,{onRow=null,limit=1500}={}){const wrap=newEl('div','data-table-wrap');const t=newEl('table','data-table');const th=newEl('thead'),tr=newEl('tr');headers.forEach(h=>tr.append(newEl('th','',String(h))));th.append(tr);t.append(th);const b=newEl('tbody');rows.slice(0,limit).forEach((row,i)=>{const tr=newEl('tr',onRow?'table-clickable':'');row.forEach(col=>{const td=newEl('td');if(col instanceof Node)td.append(col);else td.textContent=String(col??'');tr.append(td)});if(onRow)tr.addEventListener('click',()=>onRow(i));b.append(tr)});t.append(b);wrap.append(t);if(rows.length>limit)wrap.append(newEl('p','muted',`Showing ${limit.toLocaleString()} of ${rows.length.toLocaleString()} rows.`));return wrap}
