  // Text, markup, JSON, CSV and notebook rendering (all user strings are added as textContent).
  function jsonTree(data,depth=0,tracking={nodes:0}){const root=newEl('div','tree-root');function walk(value,d,key){tracking.nodes++;if(tracking.nodes>2000){root.append(newEl('div','tree-leaf','… additional nodes omitted'));return}const container=newEl('div');if(value!==null&&typeof value==='object'&&d<9){const items=Array.isArray(value)?value:Object.entries(value);const entries=Array.isArray(value)?value.map((v,i)=>[String(i),v]):items;const details=newEl('details');if(d<=1)details.open=true;const summary=newEl('summary');const title=newEl('span','tree-key',key==null?'root':key);summary.append(title,document.createTextNode(` ${Array.isArray(value)?`[${entries.length}]`:`{${entries.length}}`}`));details.append(summary);for(const [k,v]of entries.slice(0,200))details.append(walk(v,d+1,k));if(entries.length>200)details.append(newEl('div','tree-leaf',`… ${entries.length-200} more entries`));container.append(details)}else{const val=value===null?'null':typeof value==='string'?JSON.stringify(value).slice(0,550):JSON.stringify(value);const leaf=newEl('div','tree-leaf');leaf.append(newEl('span','tree-key',(key==null?'':key+': ')),document.createTextNode(val??'undefined'));container.append(leaf)}return container}root.append(walk(data,depth,null));return root}
