  async function binaryView(r,full){const bytes=new Uint8Array(await r.file.slice(0,Math.min(r.file.size,512*1024)).arrayBuffer()),str=extractedStrings(bytes,full?200:35),meta=metadataFromBinary(bytes,r.detected);const root=newEl('div');root.append(metrics([['Bytes',fmtSize(r.file.size)],['Format',r.detected.extension.toUpperCase()],['Signatures',r.detected.confidence]]));if(meta.length)root.append(panel('Parsed header fields',kv(meta)));if(bytes.length)root.append(byteDistribution(bytes.subarray(0,131072)));root.append(panel('Raw file header',codeBlock(hex(bytes.subarray(0,256)).match(/.{1,64}/g)?.join('\n')||'(empty file)')));if(str.length)root.append(panel('Printable strings (sample)',table(['Offset','String'],str.map(s=>['0x'+s.offset.toString(16),s.text]))));root.append(fallbackNote(r.detected.category==='binary'?`This file has been opened as bytes, but its complete internal format is not implemented. You can inspect its contents in Hex and Text. ${r.detected.signature}.`:'Semantic decoding is unavailable for this view. The full file remains inspectable through the Hex tab.'));return root}
